using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "FieryProjectionCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Sothis/FieryProjectionCustomDescription", order = 0)]
public class FieryProjectionCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		FieryProjectionAction fieryProjectionAction = battleAction as FieryProjectionAction;
		string text = "";
		if (fieryProjectionAction.GainEffect)
		{
			text = fieryProjectionAction.GainEffectAction.GetActionDescription(fieryProjectionAction.GainEffectAmount) + "\n";
		}
		string firstArgument = fieryProjectionAction.PurifyCorruptAction.GetActionDescription(-1).RemoveLast();
		return text + base.localizationManager.GetLocalizedWhereX(firstArgument, y: false, GetRawLocalizedDescription(battleAction));
	}
}
